css:
.blueshift-container {
    padding: 28px;
    background: #f4f6fa;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.blueshift-header {
    background: linear-gradient(135deg, #0f1c3f 0%, #1a2744 45%, #0e4b6e 100%);
    color: #ffffff;
    padding: 28px 32px;
    border-radius: 4px;
    margin-bottom: 24px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-left: 5px solid #06b6d4;
    box-shadow: 0 4px 20px rgba(15,28,63,0.18);
    flex-wrap: wrap;
    gap: 18px;
}
.blueshift-brand {
    display: flex;
    align-items: center;
    gap: 18px;
}
.blueshift-logo {
    font-size: 2.4rem;
    color: #06b6d4;
    line-height: 1;
}
.blueshift-header h1 {
    margin: 0 0 4px 0;
    font-size: 1.45rem;
    font-weight: 600;
    letter-spacing: 0.01em;
}
.blueshift-subtitle {
    font-size: 0.78rem;
    color: #a8d8ec;
    letter-spacing: 0.1em;
    text-transform: uppercase;
}
.blueshift-period-counter {
    background: rgba(6,182,212,0.15);
    border: 1px solid rgba(6,182,212,0.4);
    padding: 10px 20px;
    border-radius: 4px;
    font-size: 0.95rem;
    font-weight: 500;
    color: #ffffff;
}
.blueshift-period-counter #currentDay,
.blueshift-period-counter #maxPeriods {
    color: #67e8f9;
    font-weight: 700;
}
.blueshift-briefing {
    background: #ffffff;
    border-left: 4px solid #0e4b6e;
    padding: 22px 26px;
    margin-bottom: 24px;
    border-radius: 4px;
    box-shadow: 0 1px 6px rgba(15,28,63,0.06);
}
.blueshift-briefing-tag {
    color: #0e4b6e;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-weight: 700;
    margin-bottom: 8px;
}
.blueshift-briefing-title {
    font-size: 1.15rem;
    font-weight: 600;
    color: #0f1c3f;
    margin-bottom: 10px;
}
.blueshift-briefing-text {
    color: #425268;
    line-height: 1.55;
    font-size: 0.95rem;
}
.blueshift-status-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.blueshift-kpi {
    background: #ffffff;
    border-top: 3px solid #1a2744;
    padding: 20px 18px;
    border-radius: 4px;
    box-shadow: 0 1px 4px rgba(15,28,63,0.06);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.blueshift-kpi:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 18px rgba(15,28,63,0.1);
}
.blueshift-kpi-accent {
    border-top-color: #06b6d4;
    background: linear-gradient(180deg, #ecfeff 0%, #ffffff 60%);
}
.blueshift-kpi-label {
    color: #6b7890;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-weight: 600;
    margin-bottom: 10px;
}
.blueshift-kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #0f1c3f;
    letter-spacing: -0.01em;
}
.blueshift-kpi-accent .blueshift-kpi-value {
    color: #0891b2;
}
.blueshift-panel {
    background: #ffffff;
    border: 1px solid #e3e8f0;
    border-radius: 4px;
    padding: 26px 28px;
    margin-bottom: 20px;
    box-shadow: 0 1px 4px rgba(15,28,63,0.04);
}
.blueshift-panel h3 {
    margin: 0 0 6px 0;
    font-size: 1.1rem;
    font-weight: 600;
    color: #0f1c3f;
    border-bottom: 2px solid #06b6d4;
    padding-bottom: 10px;
    display: inline-block;
}
.blueshift-panel p {
    color: #425268;
    font-size: 0.9rem;
    margin: 14px 0 20px 0;
    line-height: 1.5;
}
.blueshift-field {
    display: grid;
    grid-template-columns: 1fr 1.4fr;
    align-items: center;
    gap: 18px;
    margin-bottom: 14px;
}
.blueshift-field label {
    font-size: 0.88rem;
    font-weight: 500;
    color: #2d3f5b;
    margin: 0;
}
.blueshift-panel input[type=number],
.blueshift-panel select {
    background: #f8fafc;
    border: 1px solid #cbd5e1;
    color: #0f1c3f;
    border-radius: 4px;
    padding: 9px 12px;
    font-size: 0.92rem;
    width: 100%;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.blueshift-panel input[type=number]:focus,
.blueshift-panel select:focus {
    outline: none;
    border-color: #06b6d4;
    box-shadow: 0 0 0 3px rgba(6,182,212,0.15);
}
.blueshift-panel select option {
    background: #ffffff;
    color: #0f1c3f;
}
.blueshift-actions {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-bottom: 28px;
    flex-wrap: wrap;
}
.blueshift-actions .btn-primary {
    background: #0f1c3f;
    border: none;
    padding: 12px 28px;
    border-radius: 4px;
    font-weight: 600;
    font-size: 0.95rem;
    letter-spacing: 0.03em;
    color: #ffffff;
    transition: background 0.2s ease, transform 0.15s ease;
}
.blueshift-actions .btn-primary:hover {
    background: #0891b2;
    transform: translateY(-1px);
}
.blueshift-actions .btn-outline-secondary {
    border: 1px solid #cbd5e1;
    color: #2d3f5b;
    padding: 10px 18px;
    border-radius: 4px;
    background: #ffffff;
}
.blueshift-actions .btn-outline-secondary:hover {
    background: #f4f6fa;
    color: #0f1c3f;
    border-color: #0f1c3f;
}
.blueshift-history-wrap,
.blueshift-chart-wrap {
    background: #ffffff;
    border: 1px solid #e3e8f0;
    border-radius: 4px;
    padding: 24px 26px;
    margin-bottom: 20px;
    box-shadow: 0 1px 4px rgba(15,28,63,0.04);
}
.blueshift-history-wrap h3 {
    margin: 0 0 14px 0;
    font-size: 1.05rem;
    font-weight: 600;
    color: #0f1c3f;
}
.blueshift-chart-wrap {
    height: 320px;
    position: relative;
}
.blueshift-container table {
    color: #1a2744;
    font-size: 0.88rem;
    width: 100%;
    margin-bottom: 0;
}
.blueshift-container table th {
    background: #0f1c3f;
    color: #e5edf7;
    font-weight: 600;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border: none;
    padding: 10px 12px;
}
.blueshift-container table td {
    border-top: 1px solid #e3e8f0;
    vertical-align: middle;
    padding: 10px 12px;
}
@media (max-width: 768px) {
    .blueshift-header { flex-direction: column; align-items: flex-start; }
    .blueshift-field { grid-template-columns: 1fr; gap: 6px; }
    .blueshift-actions { flex-direction: column; align-items: stretch; }
    .blueshift-kpi-value { font-size: 1.5rem; }
}

