            };
        }

        getChartData(state) {
            var labels = state.domainState.scoreHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                },
                dimensionChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.coherenceHistory },
                        { data: state.domainState.viabilityHistory },
                        { data: state.domainState.executionHistory },
                        { data: state.domainState.innovationHistory }
                    ]
                }
            };
        }

        getHint(state, results) {
            var period = state.currentPeriod;
            if (!results) return null;
            if (period === 1 && results.diagnosisAccuracy < 60) return window.mySimulation.t('hint_r1');
            if (period === 2 && results.themeMatches < 3) return window.mySimulation.t('hint_r2');
            if (period === 3 && results.targetingMatch < 2) return window.mySimulation.t('hint_r3');
            if (period === 4 && results.paybackYears > 4) return window.mySimulation.t('hint_r4');
            if (period === 5 && results.executionScore < 60) return window.mySimulation.t('hint_r5');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.period',     label: 'Round',       i18nKey: 'col_round' },
                { key: 'results.totalScore', label: 'Round Score', i18nKey: 'col_score',
                  formatter: function(v) { return (v || 0) + ' / 100'; } },
                { key: 'results.event',      label: 'Feedback',    i18nKey: 'col_event' }
            ];
        }

        getPresets() { return null; }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = window.mySimulation.state.domainState;
            var insights = [];
            if (ds.strategicCoherence >= 75) {
                insights.push('Strong strategic coherence: the Four Actions align with the target segment.');
            } else {
                insights.push('Strategic coherence was limited: eliminate, reduce, raise, create choices did not reinforce a single value curve.');
            }
            if (ds.financialViability >= 70) {
                insights.push('Business model is financially viable with acceptable payback and margin.');
            } else {
                insights.push('Business model economics were fragile: revisit pricing, investment level, or partnership trade-offs.');
            }
            if (ds.executionFeasibility >= 70) {
                insights.push('Execution plan is credible: organizational design and tempo support the transition.');
            } else {
                insights.push('Execution plan underestimates organizational inertia: consider a separate unit with moderated tempo.');
            }
            if (ds.innovation >= 70) {
                insights.push('Innovation depth is strong: strategy goes beyond incremental red ocean moves.');
            }
            var performance = 'Developing';
            if (ds.totalScore >= 80) performance = 'Excellent';
            else if (ds.totalScore >= 65) performance = 'Strong';
            else if (ds.totalScore >= 50) performance = 'Competent';
            return {
                totalScore: ds.totalScore,
                strategicCoherence: ds.strategicCoherence,
                financialViability: ds.financialViability,
                executionFeasibility: ds.executionFeasibility,
                innovation: ds.innovation,
                strategicTheme: ds.strategicTheme || 'undefined',
                performance: performance,
                insights: insights
            };
        }

